import { type APIRequestContext } from "@playwright/test";
import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

async function createDraftVendor(member: APIRequestContext): Promise<string> {
  const res = await member.post("/api/vendors", {
    data: {
      name: uniqueName("DOC-04 Vendor"),
      category: "services",
      contact_email: `doc04.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(res.status(), await res.text()).toBe(201);
  const vendor = (await res.json()) as { id: string; status: string };
  expect(vendor.status, await res.text()).toBe("draft");
  return vendor.id;
}

test("rejects an empty W-9 upload with empty_file", { tag: "@DOC-04" }, async ({ apiAs }) => {
  const member = await apiAs("member");
  const vendorId = await createDraftVendor(member);

  const res = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "empty.txt", mimeType: "text/plain", buffer: Buffer.alloc(0) },
    },
  });

  expect(res.status(), await res.text()).toBe(422);
  expect((await res.json()).error.code, await res.text()).toBe("empty_file");
});

test("rejects a W-9 over 10 MiB with file_too_large", { tag: "@DOC-04" }, async ({ apiAs }) => {
  const member = await apiAs("member");
  const vendorId = await createDraftVendor(member);

  const res = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "big.txt",
        mimeType: "text/plain",
        buffer: Buffer.alloc(TEN_MIB + 1, "x"),
      },
    },
  });

  expect(res.status(), await res.text()).toBe(413);
  expect((await res.json()).error.code, await res.text()).toBe("file_too_large");
});

